# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено вычислением; условие сверено с текстом учебника (задачи 32–33, с. 414)"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_?_32_2", r"в условии потеряна запятая десятичной дроби: в учебнике число вида $6n-n^{2}-7{,}5$ (было «$6n-n^{2}-7$, $5$»). Проверка: $\frac{b_{1}}{1+q}=b_{1}q(6n-n^{2}-7{,}5)$, $q(1+q)\in(0;2)$, значит $6n-n^{2}-7{,}5>\frac12$, $(n-3)^{2}<1$, $n=3$ — ключ верен",
  q=r"Знаменатель бесконечно убывающей геометрической прогрессии положителен. Найдите все целые числа $n$, для каждого из которых сумма её членов с нечётными номерами больше суммы её членов с чётными номерами на величину, равную произведению её второго члена и числа вида $6n-n^{2}-7{,}5$.")
E("G11_TB_?_33_1", r"центр прогрессии $c$: $\sum x^{5}=c(6c^{4}+10c^{2}\Sigma x^{2}+5\Sigma x^{4})=0\Rightarrow c=0$; члены $\pm\frac d2,\pm\frac{3d}2,\pm\frac{5d}2$; $\sum x^{4}=\frac{1414}{16}d^{4}=49\Rightarrow d^{4}=\frac{56}{101}$; $a_{1}=-\frac52 d$. Ключ $-2{,}5$ (это $d=1$) не удовлетворяет условию: при $d=1$ сумма четвёртых степеней $\frac{707}{8}\ne49$; проверено sympy",
  k=r"$-\dfrac{5}{2}\sqrt[4]{\dfrac{56}{101}}$",
  dnew={0: (r"$-2{,}5$", r"Ученик взял шаг $d=1$ и не проверил сумму четвёртых степеней: при $d=1$ она равна $\frac{707}{8}$, а не $49$; из условия $\frac{1414}{16}d^{4}=49$ получается $d^{4}=\frac{56}{101}$."),
        1: (r"$\dfrac{5}{2}\sqrt[4]{\dfrac{56}{101}}$", r"Ученик верно нашёл $d=\sqrt[4]{56/101}$ и симметрию членов, но взял $a_{1}=+\frac52 d$; прогрессия возрастающая, поэтому первый член отрицателен: $a_{1}=-\frac52 d$."),
        2: (r"$-\dfrac{5}{2}\sqrt[4]{\dfrac{101}{56}}$", r"Ученик записал $\frac{1414}{16}d^{4}=49$, но при выражении $d^{4}$ перевернул дробь: $d^{4}=\frac{49\cdot16}{1414}=\frac{56}{101}$, а не $\frac{101}{56}$.")})
E("G11_TB_?_33_2", r"центр прогрессии $c=0$ (как в 33а), члены $-3d,\dots,3d$; $\sum x^{4}=2d^{4}(81+16+1)=196d^{4}=51\Rightarrow d^{4}=\frac{51}{196}$; прогрессия убывающая, $a_{7}=-3d$. Ключ $-3$ (это $d=1$) не удовлетворяет условию: при $d=1$ сумма четвёртых степеней равна $196\ne51$; проверено sympy",
  k=r"$-3\sqrt[4]{\dfrac{51}{196}}$",
  dnew={0: (r"$-3$", r"Ученик взял шаг $d=1$ и не проверил сумму четвёртых степеней: при $d=1$ она равна $196$, а не $51$; из условия $196d^{4}=51$ получается $d^{4}=\frac{51}{196}$."),
        1: (r"$3\sqrt[4]{\dfrac{51}{196}}$", r"Ученик верно нашёл $d^{4}=\frac{51}{196}$, но не учёл, что прогрессия убывающая: тогда седьмой член отрицателен, $a_{7}=-3\sqrt[4]{51/196}$."),
        2: (r"$-3\sqrt[4]{\dfrac{196}{51}}$", r"Ученик записал $196d^{4}=51$, но при выражении $d^{4}$ перевернул дробь: $d^{4}=\frac{51}{196}$, а не $\frac{196}{51}$.")})
